package com.example.data

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Room database entity representing a transaction log generated by the sales terminal.
 *
 * Records point-of-sale customer purchases, payment rails used, converted amounts,
 * product inventory deductions, and terminal audit logs.
 */
@Entity(
    tableName = "terminal_transaction_logs",
    indices = [
        Index(value = ["terminalId"]),
        Index(value = ["transactionType"]),
        Index(value = ["productId"]),
        Index(value = ["timestamp"]),
        Index(value = ["status"]),
        Index(value = ["referenceCode"])
    ]
)
data class TerminalTransactionLogEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,

    @ColumnInfo(name = "terminalId")
    val terminalId: String = "POS-TERM-01",

    @ColumnInfo(name = "transactionType")
    val transactionType: String = "SALE", // "SALE", "REFUND", "RESTOCK", "PAYMENT"

    @ColumnInfo(name = "productId")
    val productId: Long? = null,

    @ColumnInfo(name = "productName")
    val productName: String? = null,

    @ColumnInfo(name = "productSku")
    val productSku: String? = null,

    @ColumnInfo(name = "quantity")
    val quantity: Int = 1,

    @ColumnInfo(name = "unitPrice")
    val unitPrice: Double = 0.0,

    @ColumnInfo(name = "totalAmount")
    val totalAmount: Double = 0.0,

    @ColumnInfo(name = "currencyCode")
    val currencyCode: String = "USD",

    @ColumnInfo(name = "amountInUsd")
    val amountInUsd: Double = 0.0,

    @ColumnInfo(name = "paymentMethod")
    val paymentMethod: String = "CARD", // "CARD", "CASH", "QR_CODE", "NFC", "ONLINE"

    @ColumnInfo(name = "paymentRail")
    val paymentRail: String = "DEFAULT",

    @ColumnInfo(name = "customerName")
    val customerName: String = "Walk-in Customer",

    @ColumnInfo(name = "status")
    val status: String = "COMPLETED", // "COMPLETED", "PENDING", "FAILED", "VOIDED"

    @ColumnInfo(name = "referenceCode")
    val referenceCode: String = "",

    @ColumnInfo(name = "timestamp")
    val timestamp: Long = System.currentTimeMillis(),

    @ColumnInfo(name = "notes")
    val notes: String? = null
)
